import{_ as a,o as i,c as o,a5 as l}from"./chunks/framework.DrDMl0tG.js";const m=JSON.parse('{"title":"Changelog: v2.4","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.4.md","filePath":"sections/changelog/v2.4.md"}'),t={name:"sections/changelog/v2.4.md"};function s(r,e,n,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="changelog-v2-4" tabindex="-1">Changelog: v2.4 <a class="header-anchor" href="#changelog-v2-4" aria-label="Permalink to &quot;Changelog: v2.4&quot;">​</a></h1><h2 id="v2-4-7-2026-08-15" tabindex="-1">v2.4.7 (2026-08-15) <a class="header-anchor" href="#v2-4-7-2026-08-15" aria-label="Permalink to &quot;v2.4.7 (2026-08-15)&quot;">​</a></h2><ul><li><code>World</code> aborts when headers and <code>libraisim</code> layouts differ.</li><li>Validation: time step, mass/inertia, zero quaternions, unknown link/joint names, collision edits.</li><li><code>SingleBodyObject::setMassProperties</code>; fixed gyroscopic modes (energy-conserving implicit midpoint) and kinematic bodies; correct capsule/cylinder inertia.</li><li><code>ArticulatedSystem</code> fixes: <code>getJointCoordinate</code> by joint type, frame <code>setExternalForce</code> in world frame, composite COM/mass matrix, collision group/mask kept.</li><li><code>HeightMap</code>: <code>setPosition</code> moves collision and rays; <code>getContactHeight</code>; transactional validated updates; mutable <code>getHeightMap()</code> removed; 16-bit PNG fix.</li><li>Heightmap contacts, swept CCD and rays corrected; consistent contact normals; MPR and mesh validation fixes.</li><li>Granular: periodic minimum image, momentum conservation across substeps, articulated coupling; constraint energy/tension fixes.</li><li>MJCF <code>&lt;equality&gt;&lt;connect&gt;</code> creates pin constraints; many MJCF/URDF/USD loader fixes and validations.</li><li>Sensor property validation; fisheye FOV up to π.</li><li>XML parser hardening; math-library bounds fixes.</li><li><code>RaisimServer</code> rejects malformed requests per connection; transactional spawn/edit.</li></ul><h2 id="v2-4-6-2026-08-11" tabindex="-1">v2.4.6 (2026-08-11) <a class="header-anchor" href="#v2-4-6-2026-08-11" aria-label="Permalink to &quot;v2.4.6 (2026-08-11)&quot;">​</a></h2><ul><li>Faster broadphase (SAP −51% dense, no-broadphase −64%), box–cylinder, MPR and GJK, heightmap contacts and <code>HeightMap::update</code>.</li><li>Contact solver skips unchanged contacts exactly; granular skips redundant grid rebuild.</li><li>Faster rayrai frame caching and material apply.</li><li><code>Weather</code>: <code>automaticUtcOffset</code>, <code>utcOffsetHours</code>.</li></ul><h2 id="v2-4-5-2026-08-02" tabindex="-1">v2.4.5 (2026-08-02) <a class="header-anchor" href="#v2-4-5-2026-08-02" aria-label="Permalink to &quot;v2.4.5 (2026-08-02)&quot;">​</a></h2><ul><li>Contact solver: no self-confirmation sweep (stress −24.5%), devirtualized updates, cheaper rank check.</li><li>ABA contact pass shares basis propagation (−43% at 8 contacts/body); principal-axis revolute fast path (~7%).</li><li>Convex mesh vs heightmap −20%.</li><li>Fixed: blended friction cone, MPR hang on deformables, capsule inertia, <code>matScalarMul</code>, terrain rounding, deformable substep velocity, sphere-on-cylinder NaN, ray inside sphere, 0-DOF systems.</li><li>Joint velocity limit defaults to infinity (ranged MJCF joints no longer frozen).</li><li><code>Path</code> normalization rewritten; MJCF material/fixed-child/slide-range fixes; typeless geoms are spheres.</li><li>Debug and Release installs coexist; <code>RAISIM_INSTALL_CONFIG</code>; Linux built for Ubuntu 20.04.</li><li>TCP viewer: non-blocking auto-connect, drains all messages per frame, clean reconnect.</li></ul><h2 id="v2-4-4-2026-06-21" tabindex="-1">v2.4.4 (2026-06-21) <a class="header-anchor" href="#v2-4-4-2026-06-21" aria-label="Permalink to &quot;v2.4.4 (2026-06-21)&quot;">​</a></h2><ul><li>ABA/articulated dynamics speedups (up to −7%); allocation-free RNE.</li><li>Mesh BVH and ray queries reuse scratch stacks (−9%).</li><li>Math fixes: aliasing-safe <code>matmul</code>, <code>cholInv2</code> overflow, rectangular <code>fillSub</code>, block/row refs.</li><li>Frame lookups fail with an error when not found.</li><li>Server serialization fixes.</li><li><code>run_tests.sh</code>/<code>run_benchmarks.sh</code> wrappers.</li></ul><h2 id="v2-4-3-2026-06-13" tabindex="-1">v2.4.3 (2026-06-13) <a class="header-anchor" href="#v2-4-3-2026-06-13" aria-label="Permalink to &quot;v2.4.3 (2026-06-13)&quot;">​</a></h2><ul><li>Contact solver: warm start, skip unchanged contacts, early stop and stall detection (primitive pile −54%, Atlas pile −75%).</li><li>Fixed deformable/granular warm-start read and destructor alignment.</li><li><code>SingleBodyObject::setPosition(Vec&lt;3&gt;)</code>.</li><li>TCP viewer reads all server contact layouts.</li><li>One shared OpenUSD runtime for raisim and rayrai; Windows <code>/FS</code> build fix.</li></ul><h2 id="v2-4-2-2026-06-09" tabindex="-1">v2.4.2 (2026-06-09) <a class="header-anchor" href="#v2-4-2-2026-06-09" aria-label="Permalink to &quot;v2.4.2 (2026-06-09)&quot;">​</a></h2><ul><li><code>try_lock()</code> on <code>World</code>, objects, constraints, sensors and server visuals.</li><li>Server: Windows <code>SOCKET</code> fix; viewer forces wake sleeping bodies.</li><li>TCP viewer: scene-reset slowdown fixed, disconnect status, <code>--wait-for-server</code> fix.</li><li>rayrai: async auto-exposure, render caches, hardened fuzz-tested protocol reader, graceful shader failures.</li><li>Binary STL with undefined alpha loads opaque.</li><li>macOS x86_64 OpenUSD; source installs on macOS build OpenUSD when it is missing.</li></ul><h2 id="v2-4-1-2026-06-06" tabindex="-1">v2.4.1 (2026-06-06) <a class="header-anchor" href="#v2-4-1-2026-06-06" aria-label="Permalink to &quot;v2.4.1 (2026-06-06)&quot;">​</a></h2><ul><li>macOS arm64 and x86_64 packages.</li><li>rayrai foliage: atlases, GPU and Hi-Z culling, multi-draw indirect, hierarchical clusters, impostors, shadow LOD, alpha-depth prepass.</li><li>Cached static/dynamic shadows; on-disk mesh preprocess cache and automatic mesh LOD.</li><li><code>InstancedVisuals::addInstances</code>, <code>reserveInstances</code> and foliage policies.</li></ul><h2 id="v2-4-0-2026-06-01" tabindex="-1">v2.4.0 (2026-06-01) <a class="header-anchor" href="#v2-4-0-2026-06-01" aria-label="Permalink to &quot;v2.4.0 (2026-06-01)&quot;">​</a></h2><ul><li>USD Physics articulations: <code>World::addUsdArticulatedSystem</code>; <code>.usd*</code> worlds.</li><li>OpenUSD always bundled (<code>RAISIM_OPENUSD</code> removed); rayrai loads USD on Windows.</li><li>Parent–child collision filtering by collision bodies; material changes apply immediately.</li><li><code>SingleBodyObject::getDOF</code>/<code>getGeneralizedCoordinateDim</code> are <code>constexpr</code>.</li><li>TCP: mouse forces scaled by body mass, Shift-drag picking, Windows client and discovery.</li><li>rayrai: vertex displacement, terrain normal/height maps, auto parallax, foliage wind, <code>findInstancedVisuals</code>.</li></ul>',17)])])}const p=a(t,[["render",s]]);export{m as __pageData,p as default};
